window.docContents[10].resolve({"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Irreducible-representations-of-commutative-algebras-are-1-dimensional/#Chapter2___Corollary2___3___12":{"contents":"Corollary 2.3.12. Let A be a commutative algebra. Then every irreducible finite dimensional representation V of A is 1-dimensional.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.3. Representations\tIrreducible representations of commutative algebras are 1-dimensional","header":"Irreducible representations of commutative algebras are 1-dimensional","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Irreducible-representations-of-commutative-algebras-are-1-dimensional/#Chapter2___Corollary2___3___12"},"/5___-Representations-of-finite-groups___-Further-results/5___10___-Frobenius-reciprocity/Section-5___10___-Frobenius-reciprocity/#Chapter5___Introduction_5___10___heading-1":{"contents":"A very important result about induced representations is the Frobenius reciprocity theorem which connects the operations Ind and Res.\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.10. Frobenius reciprocity\tSection 5.10: Frobenius reciprocity","header":"5.10. Frobenius reciprocity","id":"/5___-Representations-of-finite-groups___-Further-results/5___10___-Frobenius-reciprocity/Section-5___10___-Frobenius-reciprocity/#Chapter5___Introduction_5___10___heading-1"},"/7___-Introduction-to-categories/7___2___-Functors/#chapter-07___section-7-2":{"contents":"\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories","header":"7.2. Functors","id":"/7___-Introduction-to-categories/7___2___-Functors/#chapter-07___section-7-2"}});
